(()=>{
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normal=s=>String(s).normalize('NFD').replace(/\p{M}/gu,'').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim();
let dispose=()=>{},basePool=null;
const levels=[['easy','Простые','Приветствия, знакомство и первые фразы'],['medium','Средние','Покупки, время, помощь и повседневные дела'],['hard','Сложные','Истории, объяснения и связная речь']];
function pool(u){if(basePool)return [...Object.entries(u.customVocabulary||{}).map(([id,w])=>({id,pt:String(w.pt).slice(0,100),ru:String(w.ru).slice(0,200),aliases:[id],lessons:[],lesson:null,level:'easy'})),...basePool];const groups=new Map(),lessons=window.BoraCourses[0].lessons;for(const [i,l]of lessons.entries())for(const w of window.BoraKit.vocabulary(l.id)){const key=normal(w.pt)+'|'+normal(w.ru),existing=groups.get(key);if(existing){existing.aliases.push(w.id);existing.lessons.push(l.id)}else groups.set(key,{...w,aliases:[w.id],lessons:[l.id],level:i<10?'easy':i<20?'medium':'hard'})}basePool=[...groups.values()];const words=[...basePool];for(const [id,w]of Object.entries(u.customVocabulary||{}))words.unshift({id,pt:String(w.pt).slice(0,100),ru:String(w.ru).slice(0,200),aliases:[id],lessons:[],lesson:null,level:'easy'});return words}
function options(){const parts=location.hash.split('?'),params=new URLSearchParams(parts[1]||''),id=parts[0].split('/')[1],lesson=window.BoraCourses[0].lessons.some(l=>l.id===id)?id:null;return{level:levels.some(([id])=>id===params.get('level'))?params.get('level'):'easy',source:params.get('mode')==='saved'?'saved':'all',lesson}}
function candidates(u,o=options()){return pool(u).filter(w=>(o.lesson?w.lessons.includes(o.lesson):w.level===o.level)&&(o.source!=='saved'||w.aliases.some(id=>u.vocabulary?.[id]?.saved)))}
const key=o=>[o.level,o.source,o.lesson||'all'].join('/');
function known(u,w){return w.aliases.some(id=>u.vocabulary?.[id]?.lastKnown===true)}
function due(u,w){return !w.aliases.some(id=>{const r=u.vocabulary?.[id];return r?.lastKnown===true&&Date.parse(r.nextReviewAt)>Date.now()})}
function queue(u){return u.wordQueues?.[key(options())]}
function start(u,o=options(),retry=false){const words=candidates(u,o),old=u.wordQueues?.[key(o)],hard=retry?new Set(old?.repeat||[]):null,selected=words.filter(w=>hard?hard.has(w.id):due(u,w)).sort((a,b)=>Math.max(0,...a.aliases.map(id=>Date.parse(u.vocabulary?.[id]?.at)||0))-Math.max(0,...b.aliases.map(id=>Date.parse(u.vocabulary?.[id]?.at)||0))).slice(0,10);u.wordQueues??={};u.wordQueues[key(o)]={version:2,key:key(o),ids:selected.map(w=>w.id),index:0,remembered:0,repeat:[],history:[],revealed:false,startedAt:new Date().toISOString()};return u.wordQueues[key(o)]}
function rate(u,remembered){const q=queue(u);if(!q||q.key!==key(options())||!q.revealed||q.index>=q.ids.length)return false;const w=pool(u).find(w=>w.id===q.ids[q.index]);if(!w)return false;u.vocabulary??={};q.history.push({index:q.index,remembered:q.remembered,repeat:[...q.repeat],states:w.aliases.map(id=>[id,u.vocabulary[id]?{...u.vocabulary[id]}:null])});q.history=q.history.slice(-1);const at=new Date().toISOString();for(const id of w.aliases){const prev=u.vocabulary[id]||{};u.vocabulary[id]={...prev,lastKnown:remembered,reviews:(prev.reviews||0)+1,at,nextReviewAt:remembered?new Date(Date.now()+3*86400000).toISOString():at}}if(remembered)q.remembered++;else q.repeat.push(w.id);q.index++;q.revealed=false;return true}
function undo(u){const q=queue(u),h=q?.history?.pop();if(!h)return false;q.index=h.index;q.remembered=h.remembered;q.repeat=h.repeat;q.revealed=true;for(const [id,state]of h.states){if(state)u.vocabulary[id]=state;else delete u.vocabulary[id]}return true}
function page(u){const o=options(),words=candidates(u,o),q=queue(u)||null,w=q?.ids[q.index]?pool(u).find(w=>w.id===q.ids[q.index]):null;let body;if(!q)body=`<section class="panel queue-start"><span class="overline">НЕБОЛЬШОЙ ШАГ КАЖДЫЙ ДЕНЬ</span><h2>${o.lesson?'Слова этого занятия':levels.find(([id])=>id===o.level)[1]+' слова'}</h2><p>Одно слово на экране. Вспомни перевод, открой ответ и отметь результат.</p><div class="queue-count"><strong>${words.filter(w=>due(u,w)).length}</strong><span>готово к изучению и повторению</span></div><button class="btn" id="queue-start" ${words.some(w=>due(u,w))?'':'disabled'}>Начать · до 10 карточек →</button>${!words.length?'<p>В этой подборке пока нет сохранённых слов. Добавь свои или выбери «Слова курса».</p>':!words.some(w=>due(u,w))?'<p>Эти слова уже отмечены как знакомые. Они вернутся на повторение через 3 дня. Можно выбрать другую сложность.</p>':''}</section>`;else if(!w)body=`<section class="panel queue-finished"><span class="queue-celebration" aria-hidden="true">✓</span><h2>${q.ids.length?'Подборка пройдена!':'Пока нет карточек'}</h2><div class="queue-summary"><span><b>${q.remembered}</b> помню</span><span><b>${q.repeat.length}</b> повторю</span></div><p>Знакомые слова вернутся через 3 дня. Трудные можно повторить сейчас или в следующей подборке.</p><div class="row">${q.repeat.length?'<button class="btn" id="queue-retry">Повторить трудные →</button>':''}<button class="btn alt" id="queue-start">Следующая подборка</button></div>${q.history.length?'<button class="queue-undo" id="queue-undo">↶ Отменить последнюю отметку</button>':''}</section>`;else body=`<section class="queue-session" aria-label="Очередь слов"><div class="queue-position"><span>Карточка ${q.index+1} из ${q.ids.length}</span><button class="queue-exit" id="queue-pause">Закончить на сегодня</button></div><progress value="${q.index}" max="${q.ids.length}" aria-label="Пройдено карточек"></progress><article class="queue-card ${q.revealed?'is-revealed':''}" id="queue-card" tabindex="0" aria-label="Карточка слова"><span class="overline">${w.lesson?esc(window.BoraCourses[0].lessons.find(l=>l.id===w.lesson).title):'Моё слово'}</span><h2 lang="pt-BR">${esc(w.pt)}</h2>${window.BoraKit.audio(w.pt)}${q.revealed?`<div class="queue-translation" lang="ru">${esc(w.ru)}</div>`:'<p class="queue-prompt">Что это значит по-русски?</p><button class="btn alt" id="queue-reveal">Показать перевод</button>'}<button class="word-save" data-word-save="${esc(w.id)}" aria-pressed="${w.aliases.some(id=>u.vocabulary?.[id]?.saved)}">${w.aliases.some(id=>u.vocabulary?.[id]?.saved)?'✓ В моём словаре':'+ В мой словарь'}</button></article><div class="queue-actions"><button class="queue-known" id="queue-known" ${q.revealed?'':'disabled'}>← ✓ Помню</button><button class="queue-repeat" id="queue-repeat" ${q.revealed?'':'disabled'}>Повторить ↻ →</button></div><p class="queue-gesture">${q.revealed?'Можно свайпнуть: влево — помню, вправо — повторить.':'Сначала открой перевод, затем выбери «Помню» или «Повторить».'}</p>${q.history.length?'<button class="queue-undo" id="queue-undo">↶ Отменить последнюю отметку</button>':''}</section>`;const title=o.lesson?'Слова к занятию':'Учить слова';return `<div class="narrow dictionary-queue"><div class="page-heading"><span class="overline">ПО ОДНОМУ СЛОВУ. В ТВОЁМ ТЕМПЕ.</span><h1>${title}</h1><p>Вспоминай, отмечай, двигайся дальше. Всё сохраняется.</p>${o.lesson?`<a class="back" href="#courses/pt/${o.lesson}">← Вернуться к занятию</a>`:''}</div>${!o.lesson?`<div class="queue-levels" aria-label="Сложность слов">${levels.map(([id,label,description])=>`<a href="#dictionary/all?level=${id}&mode=${o.source}" ${id===o.level?'aria-current="page"':''}><b>${label}</b><small>${description}</small></a>`).join('')}</div><p class="queue-level-note">Начни с простых слов. Сложность можно менять в любое время.</p>`:''}<div class="queue-sources" aria-label="Подборка слов"><a href="#dictionary/${o.lesson||'all'}?level=${o.level}&mode=all" ${o.source==='all'?'aria-current="page"':''}>Слова курса</a><a href="#dictionary/${o.lesson||'all'}?level=${o.level}&mode=saved" ${o.source==='saved'?'aria-current="page"':''}>Мой словарь</a></div>${body}<details class="panel queue-extra"><summary>Найти слово или посмотреть список</summary><label>Поиск<input type="search" id="queue-search" maxlength="100" placeholder="Слово или перевод"></label><div id="queue-search-results"></div><button class="btn alt" id="queue-search-more" hidden>Показать ещё 10</button></details><details class="panel queue-extra"><summary>+ Добавить своё слово</summary><form id="custom-word-form"><label>Слово или фраза на португальском<input id="custom-word-pt" maxlength="100" required></label><label>Перевод по-русски<input id="custom-word-ru" maxlength="200" required></label><button class="btn">Добавить в мой словарь</button><p id="custom-word-status" role="status">До 100 своих слов. Перевод указываешь ты.</p></form></details><details class="panel queue-extra"><summary>Правила по занятиям</summary>${(o.lesson?window.BoraCourses[0].lessons.filter(l=>l.id===o.lesson):window.BoraCourses[0].lessons).map(l=>`<details><summary>${esc(l.title)}</summary><div data-rule-content="${l.id}"></div></details>`).join('')}</details><audio id="kit-player" hidden controls></audio><p id="kit-audio-status" role="status"></p></div>`}
function bind(u,save,render){if(!location.hash.startsWith('#dictionary'))return;stop();const $=s=>document.querySelector(s),paint=()=>{save();render();document.querySelector('#queue-card')?.focus?.({preventScroll:true})},on=(s,f)=>{if($(s))$(s).onclick=f};document.querySelectorAll('[data-word-save]').forEach(b=>b.onclick=()=>{const w=pool(u).find(w=>w.aliases.includes(b.dataset.wordSave));if(!w)return;const saved=!w.aliases.some(id=>u.vocabulary?.[id]?.saved);u.vocabulary??={};for(const id of w.aliases)u.vocabulary[id]={...u.vocabulary[id],saved};paint()});on('#queue-start',()=>{start(u);paint()});on('#queue-retry',()=>{start(u,options(),true);paint()});on('#queue-reveal',()=>{queue(u).revealed=true;paint()});on('#queue-known',()=>{if(rate(u,true))paint()});on('#queue-repeat',()=>{if(rate(u,false))paint()});on('#queue-undo',()=>{if(undo(u))paint()});on('#queue-pause',()=>{queue(u).paused=true;paint()});if(queue(u)?.paused){const card=$('#queue-card');if(card){card.closest('.queue-session').innerHTML='<section class="panel"><h2>На сегодня достаточно</h2><p>Очередь сохранена. Продолжишь с этого же слова.</p><button class="btn" id="queue-resume">Продолжить подборку →</button></section>';on('#queue-resume',()=>{delete queue(u).paused;paint()})}}
const card=$('#queue-card');if(card){let origin=null;const down=e=>{if(e.isPrimary===false||e.target.closest('button,a,audio'))return;origin={x:e.clientX,y:e.clientY}},up=e=>{if(!origin)return;const dx=e.clientX-origin.x,dy=e.clientY-origin.y;origin=null;if(Math.abs(dx)>75&&Math.abs(dx)>Math.abs(dy)*1.5&&rate(u,dx<0))paint()},cancel=()=>{origin=null},keyDown=e=>{if(e.target!==card||e.repeat||!queue(u)?.revealed)return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();if(rate(u,e.key==='ArrowLeft'))paint()}};card.addEventListener('pointerdown',down);card.addEventListener('pointerup',up);card.addEventListener('pointercancel',cancel);card.addEventListener('keydown',keyDown);dispose=()=>{card.removeEventListener('pointerdown',down);card.removeEventListener('pointerup',up);card.removeEventListener('pointercancel',cancel);card.removeEventListener('keydown',keyDown)}}
document.querySelectorAll('[data-rule-content]').forEach(box=>{const detail=box.parentElement;detail.ontoggle=()=>{if(detail.open&&!box.innerHTML)box.innerHTML=window.BoraKit.ruleHTML(box.dataset.ruleContent)}});const search=$('#queue-search');if(search){let visible=10;const update=()=>{const term=normal(search.value),matches=candidates(u).filter(w=>normal(w.pt+' '+w.ru).includes(term));$('#queue-search-results').innerHTML=matches.slice(0,visible).map(w=>`<div class="queue-search-row"><strong>${esc(w.pt)}</strong><span>${esc(w.ru)}</span></div>`).join('')||'<p>Слово не найдено. Попробуй другую сложность или добавь своё слово.</p>';$('#queue-search-more').hidden=matches.length<=visible};search.oninput=()=>{visible=10;update()};on('#queue-search-more',()=>{visible+=10;update()});update()}}
function stop(){dispose();dispose=()=>{}}
window.BoraDictionary={page,bind,stop,pool,candidates,start,rate,undo,options};
})();
